"use client"

import { Button } from "@/components/ui/button"
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuLabel,
  DropdownMenuSeparator,
  DropdownMenuTrigger,
} from "@/components/ui/dropdown-menu"
import { Avatar, AvatarFallback, AvatarImage } from "@/components/ui/avatar"
import Link from "next/link"
import { useState, useEffect } from "react"
import { User, LogOut } from 'lucide-react'
import Image from "next/image"

export function Navbar() {
  const [scrolled, setScrolled] = useState(false)
  const [isLoggedIn, setIsLoggedIn] = useState(false)
  const [user, setUser] = useState<{ id?: number; username?: string; email?: string } | null>(null)
  const [mounted, setMounted] = useState(false)

  useEffect(() => {
    const handleScroll = () => {
      setScrolled(window.scrollY > 20)
    }
    window.addEventListener("scroll", handleScroll)
    // mark mounted for client-only rendering of certain UI (avoids hydration id mismatches)
    setMounted(true)

    // Detect basic logged-in indicator from localStorage (accessToken or user)
    try {
      const storedUser = localStorage.getItem('user')
      const parsed = storedUser ? JSON.parse(storedUser) : null
      setUser(parsed)
      const hasToken = !!(localStorage.getItem('accessToken') || parsed)
      setIsLoggedIn(hasToken)
    } catch (e) {
      // ignore (e.g., SSR/localStorage not available)
    }

    // Listen for auth changes (login/logout) within the same window
    const onAuth = () => {
      try {
        const storedUser = localStorage.getItem('user')
        const parsed = storedUser ? JSON.parse(storedUser) : null
        setUser(parsed)
        setIsLoggedIn(!!(localStorage.getItem('accessToken') || parsed))
      } catch (e) {
        setUser(null)
        setIsLoggedIn(false)
      }
    }
    window.addEventListener('authChanged', onAuth)
    return () => window.removeEventListener("scroll", handleScroll)
  }, [])

  useEffect(() => {
    return () => window.removeEventListener('authChanged', () => {})
  }, [])

  async function handleLogout() {
    try {
      // Attempt server logout to revoke refresh cookie (best-effort)
      try {
        await fetch('http://localhost:5000/auth/logout', { method: 'POST', credentials: 'include' })
      } catch (_) {
        // ignore network errors
      }

      localStorage.removeItem('accessToken')
      localStorage.removeItem('user')
      setIsLoggedIn(false)
      setUser(null)
      try { window.dispatchEvent(new Event('authChanged')) } catch (e) {}
    } catch (err) {
      console.error('Logout failed', err)
    }
  }

  return (
    <nav
      className={`fixed top-0 left-0 right-0 z-50 transition-all duration-300 ${
        scrolled ? "bg-secondary/95 backdrop-blur-md shadow-lg" : "bg-secondary"
      }`}
    >
      <div className="container mx-auto px-4">
        <div className="flex items-center justify-between h-16">
          {/* Logo */}
          <Link href="/" className="flex items-center hover:opacity-90 transition-opacity">
            <Image
              src="/logo-full-transparent.svg"
              alt="Vexed Sports"
              width={160}
              height={46}
              className="h-10 w-auto"
              priority
            />
          </Link>

          {/* Navigation Links */}
          <div className="hidden md:flex items-center gap-8">
            <Link href="/" className="text-white/90 hover:text-white font-medium transition-colors relative group">
              Home
              <span className="absolute bottom-0 left-0 w-0 h-0.5 bg-white transition-all group-hover:w-full" />
            </Link>
            <Link href="/games" className="text-white/90 hover:text-white font-medium transition-colors relative group">
              Games
              <span className="absolute bottom-0 left-0 w-0 h-0.5 bg-white transition-all group-hover:w-full" />
            </Link>
            <Link href="/stats" className="text-white/90 hover:text-white font-medium transition-colors relative group">
              Stats
              <span className="absolute bottom-0 left-0 w-0 h-0.5 bg-white transition-all group-hover:w-full" />
            </Link>
            <Link
              href="/friends"
              className="text-white/90 hover:text-white font-medium transition-colors relative group"
            >
              Friends
              <span className="absolute bottom-0 left-0 w-0 h-0.5 bg-white transition-all group-hover:w-full" />
            </Link>
            <Link
              href="/admin/add-trivia"
              className="text-white/90 hover:text-white font-medium transition-colors relative group"
            >
              Add Trivia
              <span className="absolute bottom-0 left-0 w-0 h-0.5 bg-white transition-all group-hover:w-full" />
            </Link>
          </div>

          {isLoggedIn ? (
            mounted ? (
              <DropdownMenu modal={false}>
                <DropdownMenuTrigger asChild>
                  <Button
                    variant="ghost"
                    className="relative h-10 w-10 rounded-full border-2 border-white/20 hover:border-white/40 transition-all"
                  >
                    <Avatar className="h-10 w-10">
                      <AvatarImage src="/placeholder.svg" alt="JCSevigny" />
                      <AvatarFallback className="bg-primary text-white font-bold">JC</AvatarFallback>
                    </Avatar>
                  </Button>
                </DropdownMenuTrigger>
                <DropdownMenuContent className="w-56 bg-secondary/95 backdrop-blur-md border-white/10" align="end">
                  <DropdownMenuLabel className="text-white">
                    <div className="flex flex-col space-y-1">
                      <p className="text-sm font-medium">{user?.username || 'Profile'}</p>
                      <p className="text-xs text-white/60">{user?.email || ''}</p>
                    </div>
                  </DropdownMenuLabel>
                  <DropdownMenuSeparator className="bg-white/10" />
                  <DropdownMenuItem asChild className="text-white/90 hover:text-white hover:bg-white/10 cursor-pointer">
                    <Link href="/profile" className="flex items-center">
                      <User className="mr-2 h-4 w-4" />
                      Profile
                    </Link>
                  </DropdownMenuItem>
                  <DropdownMenuSeparator className="bg-white/10" />
                  <DropdownMenuItem
                    className="text-red-400 hover:text-red-300 hover:bg-red-500/10 cursor-pointer"
                    onClick={handleLogout}
                  >
                    <LogOut className="mr-2 h-4 w-4" />
                    Log out
                  </DropdownMenuItem>
                </DropdownMenuContent>
              </DropdownMenu>
            ) : (
              <Button
                variant="ghost"
                className="relative h-10 w-10 rounded-full border-2 border-white/20 transition-all"
              >
                <Avatar className="h-10 w-10">
                  <AvatarImage src="/placeholder.svg" alt="JCSevigny" />
                  <AvatarFallback className="bg-primary text-white font-bold">JC</AvatarFallback>
                </Avatar>
              </Button>
            )
          ) : (
            <Link href="/login">
              <Button
                className="bg-white text-secondary hover:bg-white/90 font-bold hover:scale-105 transition-transform"
                size="default"
              >
                Login
              </Button>
            </Link>
          )}
        </div>
      </div>
    </nav>
  )
}
